# The blocks1 variable got corrupted during copy. Let me recompute 3-blocks for demo1

def get_3_blocks(grid):
    rows, cols = len(grid), len(grid[0])
    visited = set()
    blocks = []

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 3 and (i,j) not in visited:
                block = []
                to_visit = [(i,j)]
                while to_visit:
                    ci, cj = to_visit.pop()
                    if (ci,cj) in visited:
                        continue
                    visited.add((ci,cj))
                    block.append((ci,cj))
                    for di, dj in [(-1,0), (1,0), (0,-1), (0,1)]:
                        ni, nj = ci + di, cj + dj
                        if 0 <= ni < rows and 0 <= nj < cols:
                            if grid[ni][nj] == 3 and (ni,nj) not in visited:
                                to_visit.append((ni,nj))
                blocks.append((len(block), block))
    return blocks

